import data from "./notices.json";

/**
 * The licences of everything the apps and the server ship: bundled assets and
 * npm packages grouped by identical licence text. Generated by `pnpm notices`
 * (scripts/third-party-notices.mjs); import it lazily, it's large.
 */
export type NoticeAsset = { name: string; license: string; note: string; text: string | null };
export type NoticeGroup = { license: string; text: string | null; packages: { name: string; version: string; homepage: string | null }[] };
export const notices = data as { assets: NoticeAsset[]; groups: NoticeGroup[] };
